    and encodeMediaDevice (value: MediaDevice) : JsonNode =
        match value with
        | MediaDevice.Camera -> Wire.ofString "camera"
        | MediaDevice.Microphone -> Wire.ofString "microphone"

    and encodeDeviceKind (value: DeviceKind) : JsonNode =
        match value with
        | DeviceKind.Videoinput -> Wire.ofString "videoinput"
        | DeviceKind.Audioinput -> Wire.ofString "audioinput"
        | DeviceKind.Audiooutput -> Wire.ofString "audiooutput"

    and encodeTrackKind (value: TrackKind) : JsonNode =
        match value with
        | TrackKind.Audio -> Wire.ofString "audio"
        | TrackKind.Video -> Wire.ofString "video"

    and encodeDeviceProblem (value: DeviceProblem) : JsonNode =
        match value with
        | DeviceProblem.NotFound -> Wire.ofString "notFound"
        | DeviceProblem.InUse -> Wire.ofString "inUse"
        | DeviceProblem.Overconstrained -> Wire.ofString "overconstrained"

    and encodeCaptureId (value: CaptureId) : JsonNode =
        let (CaptureId inner) = value
        Wire.ofString inner

    and encodeRecordingId (value: RecordingId) : JsonNode =
        let (RecordingId inner) = value
        Wire.ofString inner

    and encodeMediaStaleReason (value: MediaStaleReason) : JsonNode =
        match value with
        | MediaStaleReason.Unknown -> Wire.ofString "unknown"
        | MediaStaleReason.Disposed -> Wire.ofString "disposed"
        | MediaStaleReason.OtherSession -> Wire.ofString "other-session"

    and encodeDeviceInfo (value: DeviceInfo) : JsonNode =
        Wire.ofObject [ Some("deviceId", Wire.ofString value.DeviceId); Some("kind", encodeDeviceKind value.Kind); Some("label", Wire.ofString value.Label) ]

    and encodeTrackInfo (value: TrackInfo) : JsonNode =
        Wire.ofObject [ Some("kind", encodeTrackKind value.Kind); Some("label", Wire.ofString value.Label); value.Width |> Option.map (fun value -> "width", Wire.ofInt value); value.Height |> Option.map (fun value -> "height", Wire.ofInt value) ]

    and encodePreviewTarget (value: PreviewTarget) : JsonNode =
        Wire.ofObject [ Some("name", Wire.ofString value.Name); value.Key |> Option.map (fun value -> "key", Wire.ofString value) ]

    and encodeMediaRequest (value: MediaRequest) : JsonNode =
        match value with
        | MediaRequest.Permission(f_device) -> Wire.ofObject [ Some("operation", Wire.ofString "permission"); Some("device", encodeMediaDevice f_device) ]
        | MediaRequest.WatchPermission(f_device) -> Wire.ofObject [ Some("operation", Wire.ofString "watchPermission"); Some("device", encodeMediaDevice f_device) ]
        | MediaRequest.UnwatchPermission(f_device) -> Wire.ofObject [ Some("operation", Wire.ofString "unwatchPermission"); Some("device", encodeMediaDevice f_device) ]
        | MediaRequest.Devices -> Wire.ofObject [ Some("operation", Wire.ofString "devices") ]
        | MediaRequest.StartCapture(f_audio, f_video, f_audioDevice, f_videoDevice) -> Wire.ofObject [ Some("operation", Wire.ofString "startCapture"); Some("audio", Wire.ofBool f_audio); Some("video", Wire.ofBool f_video); f_audioDevice |> Option.map (fun value -> "audioDevice", Wire.ofString value); f_videoDevice |> Option.map (fun value -> "videoDevice", Wire.ofString value) ]
        | MediaRequest.Preview(f_capture, f_target) -> Wire.ofObject [ Some("operation", Wire.ofString "preview"); Some("capture", encodeCaptureId f_capture); Some("target", encodePreviewTarget f_target) ]
        | MediaRequest.Unpreview(f_target) -> Wire.ofObject [ Some("operation", Wire.ofString "unpreview"); Some("target", encodePreviewTarget f_target) ]
        | MediaRequest.Stop(f_capture) -> Wire.ofObject [ Some("operation", Wire.ofString "stop"); Some("capture", encodeCaptureId f_capture) ]
        | MediaRequest.Record(f_capture, f_mimeType) -> Wire.ofObject [ Some("operation", Wire.ofString "record"); Some("capture", encodeCaptureId f_capture); f_mimeType |> Option.map (fun value -> "mimeType", Wire.ofString value) ]
        | MediaRequest.Finish(f_recording) -> Wire.ofObject [ Some("operation", Wire.ofString "finish"); Some("recording", encodeRecordingId f_recording) ]
        | MediaRequest.Read(f_recording, f_offset, f_length) -> Wire.ofObject [ Some("operation", Wire.ofString "read"); Some("recording", encodeRecordingId f_recording); Some("offset", Wire.ofInt f_offset); Some("length", Wire.ofInt f_length) ]
        | MediaRequest.Release(f_recording) -> Wire.ofObject [ Some("operation", Wire.ofString "release"); Some("recording", encodeRecordingId f_recording) ]

    and encodeMediaResult (value: MediaResult) : JsonNode =
        match value with
        | MediaResult.Permission(f_state) -> Wire.ofObject [ Some("kind", Wire.ofString "Permission"); f_state |> Option.map (fun value -> "state", encodePermissionState value) ]
        | MediaResult.Watching(f_state) -> Wire.ofObject [ Some("kind", Wire.ofString "Watching"); Some("state", encodePermissionState f_state) ]
        | MediaResult.Unwatched -> Wire.ofObject [ Some("kind", Wire.ofString "Unwatched") ]
        | MediaResult.CannotWatch -> Wire.ofObject [ Some("kind", Wire.ofString "CannotWatch") ]
        | MediaResult.Devices(f_devices) -> Wire.ofObject [ Some("kind", Wire.ofString "Devices"); Some("devices", (Wire.ofList encodeDeviceInfo) f_devices) ]
        | MediaResult.Capturing(f_capture, f_tracks) -> Wire.ofObject [ Some("kind", Wire.ofString "Capturing"); Some("capture", encodeCaptureId f_capture); Some("tracks", (Wire.ofList encodeTrackInfo) f_tracks) ]
        | MediaResult.NothingRequested -> Wire.ofObject [ Some("kind", Wire.ofString "NothingRequested") ]
        | MediaResult.Previewing -> Wire.ofObject [ Some("kind", Wire.ofString "Previewing") ]
        | MediaResult.Unpreviewed -> Wire.ofObject [ Some("kind", Wire.ofString "Unpreviewed") ]
        | MediaResult.NotFound -> Wire.ofObject [ Some("kind", Wire.ofString "NotFound") ]
        | MediaResult.Ambiguous(f_count) -> Wire.ofObject [ Some("kind", Wire.ofString "Ambiguous"); Some("count", Wire.ofInt f_count) ]
        | MediaResult.WrongElement -> Wire.ofObject [ Some("kind", Wire.ofString "WrongElement") ]
        | MediaResult.Stopped -> Wire.ofObject [ Some("kind", Wire.ofString "Stopped") ]
        | MediaResult.RecordingStarted(f_recording, f_mimeType) -> Wire.ofObject [ Some("kind", Wire.ofString "RecordingStarted"); Some("recording", encodeRecordingId f_recording); Some("mimeType", Wire.ofString f_mimeType) ]
        | MediaResult.Recorded(f_recording, f_bytes, f_mimeType, f_durationMs) -> Wire.ofObject [ Some("kind", Wire.ofString "Recorded"); Some("recording", encodeRecordingId f_recording); Some("bytes", Wire.ofInt f_bytes); Some("mimeType", Wire.ofString f_mimeType); Some("durationMs", Wire.ofNumber f_durationMs) ]
        | MediaResult.Read(f_data, f_bytesRead, f_eof) -> Wire.ofObject [ Some("kind", Wire.ofString "Read"); Some("data", Wire.ofString f_data); Some("bytesRead", Wire.ofInt f_bytesRead); Some("eof", Wire.ofBool f_eof) ]
        | MediaResult.Released -> Wire.ofObject [ Some("kind", Wire.ofString "Released") ]
        | MediaResult.Denied -> Wire.ofObject [ Some("kind", Wire.ofString "Denied") ]
        | MediaResult.DeviceUnavailable(f_problem) -> Wire.ofObject [ Some("kind", Wire.ofString "DeviceUnavailable"); Some("problem", encodeDeviceProblem f_problem) ]
        | MediaResult.CaptureEnded -> Wire.ofObject [ Some("kind", Wire.ofString "CaptureEnded") ]
        | MediaResult.NotRecordable(f_mimeType) -> Wire.ofObject [ Some("kind", Wire.ofString "NotRecordable"); Some("mimeType", Wire.ofString f_mimeType) ]
        | MediaResult.StillRecording -> Wire.ofObject [ Some("kind", Wire.ofString "StillRecording") ]
        | MediaResult.InvalidRange -> Wire.ofObject [ Some("kind", Wire.ofString "InvalidRange") ]
        | MediaResult.TooLarge(f_limit) -> Wire.ofObject [ Some("kind", Wire.ofString "TooLarge"); Some("limit", Wire.ofInt f_limit) ]
        | MediaResult.Stale(f_reason) -> Wire.ofObject [ Some("kind", Wire.ofString "Stale"); Some("reason", encodeMediaStaleReason f_reason) ]
        | MediaResult.Unavailable(f_reason) -> Wire.ofObject [ Some("kind", Wire.ofString "Unavailable"); Some("reason", encodeUnavailableReason f_reason) ]
        | MediaResult.Cancelled -> Wire.ofObject [ Some("kind", Wire.ofString "Cancelled") ]
        | MediaResult.Failed(f_reason) -> Wire.ofObject [ Some("kind", Wire.ofString "Failed"); Some("reason", Wire.ofString f_reason) ]

    and encodeMediaFact (value: MediaFact) : JsonNode =
        match value with
        | MediaFact.PermissionChanged(f_device, f_state, f_previous) -> Wire.ofObject [ Some("kind", Wire.ofString "PermissionChanged"); Some("device", encodeMediaDevice f_device); Some("state", encodePermissionState f_state); Some("previous", encodePermissionState f_previous) ]
        | MediaFact.DevicesChanged -> Wire.ofObject [ Some("kind", Wire.ofString "DevicesChanged") ]
        | MediaFact.TrackEnded(f_capture, f_track) -> Wire.ofObject [ Some("kind", Wire.ofString "TrackEnded"); Some("capture", encodeCaptureId f_capture); Some("track", encodeTrackKind f_track) ]
        | MediaFact.CaptureEnded(f_capture) -> Wire.ofObject [ Some("kind", Wire.ofString "CaptureEnded"); Some("capture", encodeCaptureId f_capture) ]
        | MediaFact.RecordingInterrupted(f_recording, f_reason) -> Wire.ofObject [ Some("kind", Wire.ofString "RecordingInterrupted"); Some("recording", encodeRecordingId f_recording); Some("reason", Wire.ofString f_reason) ]

    /// The wire text of a PermissionState value.
    let wirePermissionState (value: PermissionState) : string =
        match value with
        | PermissionState.Granted -> "granted"
        | PermissionState.Denied -> "denied"
        | PermissionState.Prompt -> "prompt"

    /// The wire text of a UnavailableReason value.
    let wireUnavailableReason (value: UnavailableReason) : string =
        match value with
        | UnavailableReason.NotSupported -> "notSupported"
        | UnavailableReason.InsecureContext -> "insecureContext"
        | UnavailableReason.BlockedByPolicy -> "blockedByPolicy"

    /// The wire text of a MediaDevice value.
    let wireMediaDevice (value: MediaDevice) : string =
        match value with
        | MediaDevice.Camera -> "camera"
        | MediaDevice.Microphone -> "microphone"

    /// The wire text of a DeviceKind value.
    let wireDeviceKind (value: DeviceKind) : string =
        match value with
        | DeviceKind.Videoinput -> "videoinput"
        | DeviceKind.Audioinput -> "audioinput"
        | DeviceKind.Audiooutput -> "audiooutput"

    /// The wire text of a TrackKind value.
    let wireTrackKind (value: TrackKind) : string =
        match value with
        | TrackKind.Audio -> "audio"
        | TrackKind.Video -> "video"

    /// The wire text of a DeviceProblem value.
    let wireDeviceProblem (value: DeviceProblem) : string =
        match value with
        | DeviceProblem.NotFound -> "notFound"
        | DeviceProblem.InUse -> "inUse"
        | DeviceProblem.Overconstrained -> "overconstrained"

    /// The wire text of a MediaStaleReason value.
    let wireMediaStaleReason (value: MediaStaleReason) : string =
        match value with
        | MediaStaleReason.Unknown -> "unknown"
        | MediaStaleReason.Disposed -> "disposed"
        | MediaStaleReason.OtherSession -> "other-session"

    let parsePermissionState (json: string) = Wire.parse decodePermissionState json
    let serializePermissionState (value: PermissionState) = (encodePermissionState value).ToJsonString()
    let parseUnavailableReason (json: string) = Wire.parse decodeUnavailableReason json
    let serializeUnavailableReason (value: UnavailableReason) = (encodeUnavailableReason value).ToJsonString()
    let parseMediaDevice (json: string) = Wire.parse decodeMediaDevice json
    let serializeMediaDevice (value: MediaDevice) = (encodeMediaDevice value).ToJsonString()
    let parseDeviceKind (json: string) = Wire.parse decodeDeviceKind json
    let serializeDeviceKind (value: DeviceKind) = (encodeDeviceKind value).ToJsonString()
    let parseTrackKind (json: string) = Wire.parse decodeTrackKind json
    let serializeTrackKind (value: TrackKind) = (encodeTrackKind value).ToJsonString()
    let parseDeviceProblem (json: string) = Wire.parse decodeDeviceProblem json
    let serializeDeviceProblem (value: DeviceProblem) = (encodeDeviceProblem value).ToJsonString()
    let parseCaptureId (json: string) = Wire.parse decodeCaptureId json
    let serializeCaptureId (value: CaptureId) = (encodeCaptureId value).ToJsonString()
    let parseRecordingId (json: string) = Wire.parse decodeRecordingId json
    let serializeRecordingId (value: RecordingId) = (encodeRecordingId value).ToJsonString()
    let parseMediaStaleReason (json: string) = Wire.parse decodeMediaStaleReason json
    let serializeMediaStaleReason (value: MediaStaleReason) = (encodeMediaStaleReason value).ToJsonString()
    let parseDeviceInfo (json: string) = Wire.parse decodeDeviceInfo json
    let serializeDeviceInfo (value: DeviceInfo) = (encodeDeviceInfo value).ToJsonString()
    let parseTrackInfo (json: string) = Wire.parse decodeTrackInfo json
    let serializeTrackInfo (value: TrackInfo) = (encodeTrackInfo value).ToJsonString()
    let parsePreviewTarget (json: string) = Wire.parse decodePreviewTarget json
    let serializePreviewTarget (value: PreviewTarget) = (encodePreviewTarget value).ToJsonString()
    let parseMediaRequest (json: string) = Wire.parse decodeMediaRequest json
    let serializeMediaRequest (value: MediaRequest) = (encodeMediaRequest value).ToJsonString()
    let parseMediaResult (json: string) = Wire.parse decodeMediaResult json
    let serializeMediaResult (value: MediaResult) = (encodeMediaResult value).ToJsonString()
    let parseMediaFact (json: string) = Wire.parse decodeMediaFact json
    let serializeMediaFact (value: MediaFact) = (encodeMediaFact value).ToJsonString()

/// Decode-then-encode by type name. Used only by the shared conformance runner.
[<RequireQualifiedAccess>]
module Conformance =
    let roundTrips : Map<string, string -> JsonElement -> Result<JsonNode, DecodeError>> =
        Map.ofList [
            "PermissionState", (fun path element -> Codec.decodePermissionState path element |> Result.map Codec.encodePermissionState)
            "UnavailableReason", (fun path element -> Codec.decodeUnavailableReason path element |> Result.map Codec.encodeUnavailableReason)
            "MediaDevice", (fun path element -> Codec.decodeMediaDevice path element |> Result.map Codec.encodeMediaDevice)
            "DeviceKind", (fun path element -> Codec.decodeDeviceKind path element |> Result.map Codec.encodeDeviceKind)
            "TrackKind", (fun path element -> Codec.decodeTrackKind path element |> Result.map Codec.encodeTrackKind)
            "DeviceProblem", (fun path element -> Codec.decodeDeviceProblem path element |> Result.map Codec.encodeDeviceProblem)
            "CaptureId", (fun path element -> Codec.decodeCaptureId path element |> Result.map Codec.encodeCaptureId)
            "RecordingId", (fun path element -> Codec.decodeRecordingId path element |> Result.map Codec.encodeRecordingId)
            "MediaStaleReason", (fun path element -> Codec.decodeMediaStaleReason path element |> Result.map Codec.encodeMediaStaleReason)
            "DeviceInfo", (fun path element -> Codec.decodeDeviceInfo path element |> Result.map Codec.encodeDeviceInfo)
            "TrackInfo", (fun path element -> Codec.decodeTrackInfo path element |> Result.map Codec.encodeTrackInfo)
            "PreviewTarget", (fun path element -> Codec.decodePreviewTarget path element |> Result.map Codec.encodePreviewTarget)
            "MediaRequest", (fun path element -> Codec.decodeMediaRequest path element |> Result.map Codec.encodeMediaRequest)
            "MediaResult", (fun path element -> Codec.decodeMediaResult path element |> Result.map Codec.encodeMediaResult)
            "MediaFact", (fun path element -> Codec.decodeMediaFact path element |> Result.map Codec.encodeMediaFact)
        ]
